// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/telegram", wrapper.LoginTelegram)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/dev", wrapper.LoginDev)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/me/settings", wrapper.UpdateMySettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/categories", wrapper.ListCategories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/categories", wrapper.CreateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/categories/{id}", wrapper.DeleteCategory)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/categories/{id}", wrapper.UpdateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/categories/{id}/move", wrapper.MoveCategory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/categories/{id}/archive", wrapper.ArchiveCategory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/categories/{id}/unarchive", wrapper.UnarchiveCategory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/instances", wrapper.ListInstances)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tasks", wrapper.CreateTask)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/instances/{id}", wrapper.DeleteInstance)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/instances/{id}", wrapper.UpdateInstance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/instances/running", wrapper.ListRunningInstances)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/stats", wrapper.GetStats)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instances/unplanned", wrapper.CreateUnplanned)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instances/{id}/complete", wrapper.CompleteInstance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instances/{id}/start", wrapper.StartInstance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instances/{id}/stop", wrapper.StopInstance)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/instances/{id}/tracking", wrapper.UpdateTracking)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instances/{id}/reschedule", wrapper.RescheduleInstance)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/series/{id}", wrapper.GetSeries)
	})

	return r
}

